{
  "title": "The Rescue of the Lost Heir",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A weary band approaches the ruined royal city at dawn.",
      "visual_description": "Wide shot of three figures cresting a misty hill, the shattered spires of a once-great city silhouetted against a pale orange sunrise.",
      "characters": ["Captain Veyra", "Brindle the Scout"]
    },
    {
      "scene_number": 2,
      "caption": "The map reveals the prisoner's tower.",
      "visual_description": "Close-up of a hand-drawn parchment map spread across a mossy stone, with Veyra pointing to a circled tower while Brindle leans in.",
      "characters": ["Captain Veyra", "Brindle the Scout"]
    },
    {
      "scene_number": 3,
      "caption": "Their court mage catches up, breathless and yawning.",
      "visual_description": "A robed mage stumbles down the hill clutching a glowing staff, robes askew, while the others wait with crossed arms.",
      "characters": ["Captain Veyra", "Brindle the Scout", "Mage Olwen"]
    },
    {
      "scene_number": 4,
      "caption": "At the broken castle gates, rusted iron looms.",
      "visual_description": "Massive iron-spiked gates hang twisted on their hinges, vines crawling through, the trio dwarfed beneath the archway.",
      "characters": ["Captain Veyra", "Brindle the Scout", "Mage Olwen"]
    },
    {
      "scene_number": 5,
      "caption": "Frightened townspeople whisper of the cursed tower.",
      "visual_description": "A huddle of ragged citizens in a shadowed alley, pointing fearfully toward a distant black spire wreathed in green mist.",
      "characters": ["Captain Veyra", "Goodwife Mira"]
    },
    {
      "scene_number": 6,
      "caption": "Brindle scouts the rooftops for patrols.",
      "visual_description": "Brindle crouches on a tiled rooftop, peering down at armored soldiers marching in formation through a cobbled square.",
      "characters": ["Brindle the Scout", "Iron Patrol Captain"]
    },
    {
      "scene_number": 7,
      "caption": "Tattered royal banners flutter over the empty plaza.",
      "visual_description": "A windswept plaza with torn crimson banners bearing a golden stag sigil, Veyra standing among them with a hand on her sword hilt.",
      "characters": ["Captain Veyra"]
    },
    {
      "scene_number": 8,
      "caption": "A drowsy palace steward is found napping in the archives.",
      "visual_description": "A plump steward asleep at a dusty desk, head on an open ledger, candle guttering, as Olwen gently shakes his shoulder.",
      "characters": ["Mage Olwen", "Steward Pemby"]
    },
    {
      "scene_number": 9,
      "caption": "Pemby mumbles the secret way beneath the city.",
      "visual_description": "The steward gestures sleepily at a trapdoor hidden under a moth-eaten rug, dust swirling in lantern light.",
      "characters": ["Captain Veyra", "Mage Olwen", "Steward Pemby"]
    },
    {
      "scene_number": 10,
      "caption": "Distant dragon rumors echo through the catacombs.",
      "visual_description": "The trio descend a narrow stone stair, lantern light flickering across carved reliefs of winged beasts as a low rumble shakes dust from the ceiling.",
      "characters": ["Captain Veyra", "Brindle the Scout", "Mage Olwen"]
    },
    {
      "scene_number": 11,
      "caption": "A sealed magic door bars the way forward.",
      "visual_description": "An arched door etched with glowing blue runes blocks a corridor, Olwen tracing symbols in the air while the others watch warily.",
      "characters": ["Captain Veyra", "Brindle the Scout", "Mage Olwen"]
    },
    {
      "scene_number": 12,
      "caption": "Olwen unravels the binding spell.",
      "visual_description": "Runes flare gold then dissolve, the door swinging inward into a vast vaulted chamber, Olwen's staff blazing with light.",
      "characters": ["Mage Olwen"]
    },
    {
      "scene_number": 13,
      "caption": "They find the captive heir chained in a crystal cell.",
      "visual_description": "A young noble in tattered finery slumps inside a faceted crystal prison, hands shackled, looking up as the rescuers enter.",
      "characters": ["Captain Veyra", "Brindle the Scout", "Mage Olwen", "Prince Aldric"]
    },
    {
      "scene_number": 14,
      "caption": "Brindle picks the crystalline locks.",
      "visual_description": "Close-up of slender tools twisting inside a glowing keyhole, Aldric's wrist freed as the shackle clatters to the floor.",
      "characters": ["Brindle the Scout", "Prince Aldric"]
    },
    {
      "scene_number": 15,
      "caption": "Armored patrols converge in the upper halls.",
      "visual_description": "A line of helmeted soldiers with halberds charges down a torchlit corridor, banners snapping behind them.",
      "characters": ["Iron Patrol Captain", "Captain Veyra"]
    },
    {
      "scene_number": 16,
      "caption": "Veyra holds the stairwell while the others flee.",
      "visual_description": "Sparks fly as Veyra crosses blades with the patrol captain on a narrow spiral stair, urging the others upward over her shoulder.",
      "characters": ["Captain Veyra", "Iron Patrol Captain"]
    },
    {
      "scene_number": 17,
      "caption": "The party races for the great stone bridge.",
      "visual_description": "Four figures sprint across moonlit cobbles toward a long arched bridge spanning a black chasm, the city burning behind them.",
      "characters": ["Captain Veyra", "Brindle the Scout", "Mage Olwen", "Prince Aldric"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge as Olwen collapses it behind them.",
      "visual_description": "Mid-span, Olwen turns and slams her staff down; stones crumble into the abyss as the rescuers reach the far side, dawn breaking ahead.",
      "characters": ["Captain Veyra", "Brindle the Scout", "Mage Olwen", "Prince Aldric"]
    }
  ]
}

